public class WearStandaloneAppDetector extends Detector implements Detector.XmlScanner {
    public static final Issue ISSUE = Issue.create(
        "InvalidWearFeatureAttribute",
        "Invalid attribute for Wear uses-feature",
        "For the `android.hardware.type.watch` uses-feature, `android:required=\"false\"` is disallowed. A single APK for Wear and non-Wear devices is not supported.",
        Category.CORRECTNESS,
        6,
        Severity.ERROR,
        new Implementation(WearStandaloneAppDetector.class, Scope.MANIFEST_SCOPE)
    );

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_USES_FEATURE);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String name = element.getAttribute(ATTR_NAME, ANDROID_URI);
        if (!"android.hardware.type.watch".equals(name)) {
            return;
        }
        String required = element.getAttribute(ATTR_REQUIRED, ANDROID_URI);
        if (required != null && required.equalsIgnoreCase("false")) {
            context.report(ISSUE, context.getLocation(element), "Wear apps must not set `android:required=\"false\"` for the `android.hardware.type.watch` uses-feature.");
        }
    }
}

